// ── Points tables (embedded in n8n Code nodes; also unit-tested in node) ──
// division: { points: {win, tie, no_result, loss, tiebreakers}, format }, sport: 'CRICKET' | 'FOOTBALL' | ...
// teams: [{ entry_id, group_no }], matches: [{ stage, group_no, status, home_entry_id, away_entry_id, winner_entry_id,
//   home_score, away_score, outcome, standing: [{batting, runs, balls}] }]
// Returns [{ group_no, rows: [...], complete }] with rows in finishing order.
function computeStandings(division, sport, teams, matches) {
  const pts = division.points || {};
  const P = { win: pts.win ?? 2, tie: pts.tie ?? 1, nr: pts.no_result ?? 1, loss: pts.loss ?? 0 };
  const breakers = Array.isArray(pts.tiebreakers) && pts.tiebreakers.length ? pts.tiebreakers : (sport === 'CRICKET' ? ['NRR', 'HEAD_TO_HEAD'] : ['GOAL_DIFF', 'GOALS_FOR', 'HEAD_TO_HEAD']);
  const groupMatches = matches.filter(m => m.stage === 'GROUP');
  const groupNos = [...new Set(teams.map(t => t.group_no || 1))].sort((a, b) => a - b);
  return groupNos.map(g => {
    const rows = new Map(teams.filter(t => (t.group_no || 1) === g).map(t => [t.entry_id, {
      entry_id: t.entry_id, played: 0, won: 0, lost: 0, tied: 0, no_result: 0, points: 0,
      runs_for: 0, balls_for: 0, runs_against: 0, balls_against: 0, nrr: 0, goals_for: 0, goals_against: 0, goal_diff: 0 }]));
    const inGroup = groupMatches.filter(m => (m.group_no || 1) === g);
    const results = []; // for head-to-head
    for (const m of inGroup) {
      if (m.status !== 'COMPLETED') continue;
      const h = rows.get(m.home_entry_id), a = rows.get(m.away_entry_id);
      if (!h || !a) continue;
      h.played++; a.played++;
      const outcome = m.outcome || (m.winner_entry_id ? 'WIN' : (m.home_score != null && m.home_score === m.away_score ? 'TIE' : 'NO_RESULT'));
      if (outcome === 'WIN' && m.winner_entry_id) {
        const w = rows.get(m.winner_entry_id), l = w === h ? a : h;
        if (w) { w.won++; w.points += P.win; l.lost++; l.points += P.loss; results.push([w.entry_id, l.entry_id]); }
      } else if (outcome === 'TIE') {
        h.tied++; a.tied++; h.points += P.tie; a.points += P.tie;
      } else {
        h.no_result++; a.no_result++; h.points += P.nr; a.points += P.nr;
      }
      if (sport === 'CRICKET' && outcome !== 'NO_RESULT') {
        // Net run rate uses runs and overs from both innings; abandoned matches are left out.
        for (const inn of m.standing || []) {
          const bat = rows.get(inn.batting), bowl = bat === h ? a : h;
          if (!bat) continue;
          bat.runs_for += inn.runs; bat.balls_for += inn.balls;
          bowl.runs_against += inn.runs; bowl.balls_against += inn.balls;
        }
      } else if (sport !== 'CRICKET' && m.home_score != null && m.away_score != null) {
        h.goals_for += m.home_score; h.goals_against += m.away_score;
        a.goals_for += m.away_score; a.goals_against += m.home_score;
      }
    }
    for (const r of rows.values()) {
      const rate = (runs, balls) => balls > 0 ? runs * 6 / balls : 0;
      r.nrr = Math.round((rate(r.runs_for, r.balls_for) - rate(r.runs_against, r.balls_against)) * 1000) / 1000;
      r.goal_diff = r.goals_for - r.goals_against;
    }
    const beat = (x, y) => results.some(([w, l]) => w === x && l === y);
    const key = {
      NRR: r => r.nrr, WINS: r => r.won, GOAL_DIFF: r => r.goal_diff, GOALS_FOR: r => r.goals_for,
      GAMES_DIFF: r => r.goal_diff, POINT_DIFF: r => r.goal_diff,
    };
    const sorted = [...rows.values()].sort((x, y) => {
      if (y.points !== x.points) return y.points - x.points;
      for (const b of breakers) {
        if (b === 'HEAD_TO_HEAD') {
          if (beat(x.entry_id, y.entry_id) && !beat(y.entry_id, x.entry_id)) return -1;
          if (beat(y.entry_id, x.entry_id) && !beat(x.entry_id, y.entry_id)) return 1;
          continue;
        }
        const f = key[b];
        if (f && f(y) !== f(x)) return f(y) - f(x);
      }
      return 0;
    });
    sorted.forEach((r, i) => { r.position = i + 1; });
    const complete = inGroup.length > 0 && inGroup.every(m => m.status === 'COMPLETED');
    return { group_no: g, rows: sorted, complete };
  });
}

/** When every group match is done: { 'G1#1': entryId, ... } for the knockout places. */
function qualifiers(groups) {
  const out = {};
  if (!groups.length || !groups.every(g => g.complete)) return out;
  for (const g of groups) g.rows.forEach(r => { out[`G${g.group_no}#${r.position}`] = r.entry_id; });
  return out;
}


const s = $in, r = $('Check Request').first().json;
const fail = (st, m, extra = {}) => [{ json: { ok: false, status: st, body: { success: false, message: m, ...extra } } }];
if (!s.id) return fail(404, 'Match not found.');
if (Number(s.can_score) !== 1) return fail(403, 'Enter the scoring PIN to score this match.');
const mine = Number(s.scorer_user_id) === Number(s.viewer_id);
const busy = s.scorer_user_id && !mine && Number(s.scorer_idle) < 180;
if (busy && !r.takeOver) return fail(409, `${s.scorer_name || 'Someone'} is scoring this match.`, { code: 'LOCKED', scorer: s.scorer_name });
const p = [], stmts = [];
const add = v => { p.push(v); return '$' + p.length; };
if (r.release) {
  if (mine) stmts.push(`UPDATE tournament_matches SET scorer_user_id = NULL WHERE id = ${add(s.id)}`);
  return [{ json: { ok: true, sql: stmts.join('; ') || 'SELECT 1', params: p, count: Number(s.event_count) } }];
}
if (r.base !== Number(s.event_count)) return fail(409, 'The score changed on another phone. Reloading.', { code: 'CONFLICT', event_count: Number(s.event_count) });
if (r.events.length && !r.live) return fail(422, 'Send the live score with the events.');
let count = Number(s.event_count);
for (const e of r.events) {
  count++;
  stmts.push(`INSERT INTO match_events (match_id, seq, client_id, type, data, scored_by) VALUES (${add(s.id)}, ${add(count)}, ${add(String(e.client_id))}, ${add(e.type)}, ${add(JSON.stringify(e.data || {}))}, ${add(s.viewer_id)})`);
}
// Result texts come with {entryId} placeholders; swap in team names.
const names = { [s.home_entry_id]: s.home_name || 'Home', [s.away_entry_id]: s.away_name || 'Away' };
const fill = t => t == null ? null : String(t).replace(/\{(\d+)\}/g, (_, id) => names[id] || 'Team').slice(0, 120);
const live = r.live;
const done = live && live.status === 'COMPLETED';
const runsOf = entry => { const i = (live?.innings || []).find(x => x.batting_entry_id === entry); return i ? Number(i.runs) : null; };
const winner = done && live.winner_entry_id && [s.home_entry_id, s.away_entry_id].includes(Number(live.winner_entry_id)) ? Number(live.winner_entry_id) : null;
if (live) {
  const status = done ? 'COMPLETED' : (count > 0 ? 'LIVE' : s.status);
  stmts.push(`UPDATE tournament_matches SET event_count = ${add(count)}, live = ${add(JSON.stringify({ ...live, result: fill(live.result) }))}, status = ${add(status)}, ` +
    `home_score = ${add(runsOf(s.home_entry_id))}, away_score = ${add(runsOf(s.away_entry_id))}, ` +
    `result_text = ${add(done || live.status === 'TIE_DECISION' ? fill(live.result) : null)}, winner_entry_id = ${add(winner)}, ` +
    `started_at = IF(${add(count)} > 0, COALESCE(started_at, NOW()), started_at), ended_at = ${done ? 'COALESCE(ended_at, NOW())' : 'NULL'}, ` +
    `scorer_user_id = ${add(s.viewer_id)}, scorer_seen_at = NOW() WHERE id = ${add(s.id)}`);
  if (count > 0) stmts.push(`UPDATE tournaments SET status = 'LIVE' WHERE id = ${add(s.tournament_id)} AND status IN ('REGISTRATION_OPEN', 'REGISTRATION_CLOSED', 'FIXTURES_READY')`);
  // When the last group match finishes, the group places ("1st Group A") move into the knockouts.
  if (done && s.stage === 'GROUP') {
    const parse = v => { try { return typeof v === 'string' ? JSON.parse(v) : (v || []); } catch { return []; } };
    const all = parse(s.division_matches).map(x => x.id === s.id
      ? { ...x, status: 'COMPLETED', winner_entry_id: winner, outcome: live.outcome || (winner ? 'WIN' : 'NO_RESULT'), standing: live.standing || [],
          home_score: runsOf(s.home_entry_id), away_score: runsOf(s.away_entry_id) }
      : { ...x, outcome: x.outcome && x.outcome !== 'null' ? x.outcome : null, standing: parse(x.standing) });
    const places = qualifiers(computeStandings({ points: parse(s.division_points) }, s.sport, parse(s.division_teams), all));
    for (const [ref, entry] of Object.entries(places)) {
      stmts.push(`UPDATE tournament_matches SET home_entry_id = ${add(entry)} WHERE division_id = ${add(s.division_id)} AND home_ref = ${add(ref)} AND status = 'SCHEDULED'`);
      stmts.push(`UPDATE tournament_matches SET away_entry_id = ${add(entry)} WHERE division_id = ${add(s.division_id)} AND away_ref = ${add(ref)} AND status = 'SCHEDULED'`);
    }
  }
  // The winner moves into the knockout match that was waiting for "Winner of match N".
  if (winner) {
    stmts.push(`UPDATE tournament_matches SET home_entry_id = ${add(winner)} WHERE division_id = ${add(s.division_id)} AND home_ref = ${add('W#' + s.match_no)} AND status = 'SCHEDULED'`);
    stmts.push(`UPDATE tournament_matches SET away_entry_id = ${add(winner)} WHERE division_id = ${add(s.division_id)} AND away_ref = ${add('W#' + s.match_no)} AND status = 'SCHEDULED'`);
  }
